const identityRevokeCascade = `-- name: IdentityRevokeCascade :many
WITH RECURSIVE tree(id) AS (
    SELECT t0.id FROM api_token t0 WHERE t0.id = $2::text::uuid
    UNION
    SELECT c.id FROM api_token c JOIN tree ON c.derived_from = tree.id
     OR ($4::boolean AND c.rotated_from = tree.id)
)
UPDATE api_token a
   SET revoked_at = now(), revoked_by = NULLIF($1::text, '')::uuid,
       revocation_reason = CASE WHEN a.id = $2::text::uuid THEN $3::text ELSE 'parent_revoked' END
  FROM tree
 WHERE a.id = tree.id AND a.revoked_at IS NULL
RETURNING a.id::text AS id, encode(a.secret_sha256, 'hex') AS secret_hex, a.principal_id::text AS owner_id,
          a.type, (a.id = $2::text::uuid) AS is_root
`

